// Urdu (اردو): every message the windows show, from the catalogue's list
// (messages.json), in Urdu as Pakistan writes it. The words for the suite's
// recurring terms are in GLOSSARY-ur.md beside this file, which a change of
// a word here follows. Drafted by machine and checked against the list by
// tests/catalogues.test.js; a native speaker's review is still to come.

