  'Each account keeps its own options, as in Outlook.': 'ہر اکاؤنٹ کے اختیارات الگ رہتے ہیں، جیسے Outlook میں۔',
  'Each category is written as Word\'s TOA field, its heading over it; All writes one for every category that has citations in it.': 'ہر زمرہ Word کے TOA فیلڈ کے طور پر لکھا جاتا ہے، اور اس کی سرخی اس کے اوپر؛ «سب» ہر اس زمرے کے لیے ایک فیلڈ لکھتا ہے جس میں حوالے موجود ہوں۔',
  'Each cell its own paragraph': 'ہر سیل ایک الگ پیراگراف',
  'Each is set up as Add account does: a provider in the built-in list straight away; for any other domain, its own records are looked up when you press Add (its DNS, autoconfig and autodiscover addresses), and nothing else is asked.': 'ہر ایک ویسے ہی ترتیب پاتا ہے جیسے اکاؤنٹ شامل کریں میں: بلٹ ان فہرست والا فراہم کنندہ فوراً؛ کسی اور ڈومین کے اپنے ریکارڈ شامل کریں دبانے پر ہی دیکھے جاتے ہیں (اس کا DNS، autoconfig اور autodiscover پتے)، اور کسی اور سے کچھ نہیں پوچھا جاتا۔',
  'Each line is a paragraph of its own. Ctrl+Enter puts the words in.': 'ہر لائن ایک الگ پیراگراف ہے۔ Ctrl+Enter سے الفاظ داخل ہو جاتے ہیں۔',
  'Each message is the merged letter itself. The account\'s signature is not added: what you wrote in the letter is what each person receives.': 'ہر پیغام بذاتِ خود ضم شدہ خط ہے۔ اکاؤنٹ کا دستخط شامل نہیں کیا جاتا: خط میں آپ نے جو لکھا، ہر شخص کو وہی موصول ہوتا ہے۔',
  'Each numbered level shows its own number: keep %{level} in level {level}\'s number.': 'ہر نمبر والی سطح اپنا نمبر دکھاتی ہے: سطح {level} کے نمبر میں %{level} برقرار رکھیں۔',
  'Each page is written as a picture into a folder you choose: {count} in all. This document is not changed.': 'ہر صفحہ آپ کے چنے ہوئے فولڈر میں تصویر کے طور پر لکھا جاتا ہے: کل {count}۔ یہ دستاویز نہیں بدلتی۔',
  'Each sender hears from this once while it stays on — a second message from the same person is not answered again until it is turned off and on. A mailing list, a no-reply address and a message that already says it is automatic are never answered.': 'جب تک یہ آن رہے، ہر بھیجنے والے کو یہ صرف ایک بار جواب دیتا ہے — اسی شخص کے دوسرے پیغام کا جواب تب تک نہیں دیا جاتا جب تک اسے بند کر کے دوبارہ آن نہ کیا جائے۔ میلنگ لسٹ، no-reply پتے اور ایسے پیغام کو کبھی جواب نہیں دیا جاتا جو پہلے ہی خودکار ہونے کا بتاتا ہو۔',
  'Each slide then moves on by itself after the time it was on screen, and Use Timings is turned on.': 'اس کے بعد ہر سلائیڈ اتنی دیر بعد خود بخود آگے بڑھتی ہے جتنی دیر وہ اسکرین پر رہی تھی، اور اوقات استعمال کریں آن ہو جاتا ہے۔',
  'Each ticked field gets a panel of buttons, one per item, that filters the pivot table.': 'ہر ٹک کیے گئے فیلڈ کو بٹنوں کا ایک پینل ملتا ہے، ہر آئٹم کے لیے ایک بٹن، جو PivotTable کو فلٹر کرتا ہے۔',
  'Each ticked field gets a panel of buttons, one per item, that filters the table.': 'ہر ٹک کیے گئے فیلڈ کو بٹنوں کا ایک پینل ملتا ہے، ہر آئٹم کے لیے ایک بٹن، جو ٹیبل کو فلٹر کرتا ہے۔',
