  'One account a line: the address, then its password, separated by a space, a tab, a comma, a semicolon, a colon or a bar. A first line naming the columns (email, password, name, IMAP server...) is read as a table, as a spreadsheet saves one. A line starting # is left out.': 'ہر سطر میں ایک اکاؤنٹ: پتہ، پھر اس کا پاس ورڈ، جنہیں اسپیس، ٹیب، کاما، سیمی کولن، کولن یا بار سے الگ کیا گیا ہو۔ اگر پہلی سطر کالموں کے نام دے (email, password, name, IMAP server...) تو باقی کو جدول کی طرح پڑھا جاتا ہے، جیسے اسپریڈ شیٹ محفوظ کرتی ہے۔ # سے شروع ہونے والی سطر چھوڑ دی جاتی ہے۔',
  'One column': 'ایک کالم',
  'One flow on screen for a native caret; the print and PDF layout actually splits it into columns': 'اسکرین پر ایک ہی بہاؤ تاکہ کرسر قدرتی طور پر چلے؛ پرنٹ اور PDF لے آؤٹ اسے واقعی کالمز میں تقسیم کرتا ہے',
  'One line per line. A tab moves to the centre, a second to the right.': 'ہر سطر الگ لائن پر۔ ایک ٹیب درمیان میں لے جاتا ہے، دوسرا دائیں جانب۔',
  'One range or several, such as B2:D10 F2:F10.': 'ایک رینج یا کئی، جیسے B2:D10 F2:F10۔',
  'One region marked for Everyone.': { one: '{count} حصہ سب کے لیے نشان زد ہے۔', other: '{count} حصے سب کے لیے نشان زد ہیں۔' },
  'Only Word, Excel and PowerPoint documents embed.': 'صرف Word، Excel اور PowerPoint دستاویزات ہی ایمبیڈ ہو سکتی ہیں۔',
  'Only a document has a design to set as the default.': 'صرف دستاویز کا ڈیزائن ہی بطور ڈیفالٹ سیٹ کیا جا سکتا ہے۔',
  'Only a scratch file made in this run is added to.': 'اضافہ صرف اسی عارضی فائل میں کیا جاتا ہے جو ایپ کے موجودہ سیشن میں بنی ہو۔',
  'Only a scratch file of this suite is taken as a recording.': 'ریکارڈنگ کے طور پر صرف اسی سوئٹ کی بنائی ہوئی عارضی فائل لی جاتی ہے۔',
  'Only a shape has points to edit.': 'ترمیم کے لیے پوائنٹس صرف شکل میں ہوتے ہیں۔',
  'Only a shape or a text box has words to change.': 'تبدیل کرنے کے لیے الفاظ صرف شکل یا ٹیکسٹ باکس میں ہوتے ہیں۔',
  'Only a shape or a text box has words to transform.': 'شکل بدلنے کے لیے الفاظ صرف شکل یا ٹیکسٹ باکس میں ہوتے ہیں۔',
