  'Only an entrance, emphasis or exit this writes can be played by paragraph': 'پیراگراف بہ پیراگراف صرف داخلے، زور یا اخراج کا وہی اثر چلایا جا سکتا ہے جو یہ ایپ لکھتی ہے',
  'Only certain kinds of changes can be made to this document — Review → Restrict Editing.': 'اس دستاویز میں صرف مخصوص قسم کی تبدیلیاں کی جا سکتی ہیں — جائزہ ← ترمیم محدود کریں۔',
