  'Show announcements from office.rutba.io — once a day at most. It sends the version and the operating system, and no identifier of any kind, so what is counted at the other end is "a copy opened somewhere", never you. It is also the only way we know the suite is being used at all.': 'office.rutba.io سے اعلانات دکھائیں — دن میں زیادہ سے زیادہ ایک بار۔ یہ ورژن اور آپریٹنگ سسٹم بھیجتا ہے، اور کسی بھی قسم کی کوئی شناخت نہیں، اس لیے دوسری طرف جو گنا جاتا ہے وہ "کہیں کھولی گئی ایک کاپی" ہے، آپ کبھی نہیں۔ ہمارے پاس یہ جاننے کا بھی یہی واحد طریقہ ہے کہ سوٹ استعمال ہو بھی رہا ہے یا نہیں۔',
