  'Shown when the pointer rests on the cell. Optional.': 'جب پوائنٹر سیل پر ٹھہرے تو دکھایا جاتا ہے۔ اختیاری۔',
  'Shown when the pointer rests on the cell; Excel shows it the same way.': 'جب پوائنٹر سیل پر ٹھہرے تو دکھایا جاتا ہے؛ Excel بھی اسے اسی طرح دکھاتا ہے۔',
  'Shows a list of ideas one under the other, each in a wide rounded box.': 'خیالات کی فہرست ایک کے نیچے ایک دکھاتا ہے، ہر ایک گول کونوں والے چوڑے خانے میں۔',
  'Shows each top item over the items under it — a line to each. Tab a line in to put it under the one above.': 'ہر اوپری آئٹم کو اس کے نیچے والے آئٹمز کے اوپر دکھاتا ہے — ہر ایک تک ایک لکیر۔ کسی لائن کو اوپر والی لائن کے نیچے رکھنے کے لیے اسے Tab سے اندر کریں۔',
  'Shows ideas that need not follow one another, each in a box of its own, the boxes in rows.': 'ایسے خیالات دکھاتا ہے جن کا ایک دوسرے کے بعد آنا ضروری نہیں، ہر ایک اپنے الگ خانے میں، اور خانے قطاروں میں۔',
  'Shows stages that come round again, in circles on a ring, clockwise from the top.': 'بار بار لوٹ کر آنے والے مراحل دکھاتا ہے، ایک حلقے پر دائروں میں، اوپر سے گھڑی کی سمت میں۔',
  'Shows the stages of a process moving forward, each a chevron pointing to the next.': 'کسی عمل کے آگے بڑھتے ہوئے مراحل دکھاتا ہے، ہر مرحلہ ایک شیورون جو اگلے کی طرف اشارہ کرتا ہے۔',
  'Shows the steps of a process in order, left to right, an arrow from each to the next.': 'کسی عمل کے مراحل ترتیب سے دکھاتا ہے، بائیں سے دائیں، ہر ایک سے اگلے تک ایک تیر۔',
