  'Signature saved': 'دستخط محفوظ ہو گیا',
  'Signature: your signature, typed, drawn or from a picture, placed where you click; not a digital signature': 'دستخط: آپ کے دستخط، ٹائپ کیے، بنائے یا تصویر سے، جہاں کلک کریں وہاں رکھے جاتے ہیں؛ ڈیجیٹل دستخط نہیں',
  'Signed by': 'دستخط کنندہ',
  'Signed by {name} with a certificate that is not meant for mail.': '{name} نے ایسے سرٹیفکیٹ سے دستخط کیے جو میل کے لیے نہیں۔',
  'Signed by {name}, and the message has not changed, but no authority this computer trusts vouches for the certificate.': '{name} کا دستخط شدہ، اور پیغام نہیں بدلا، مگر اس کمپیوٹر کا کوئی معتبر ادارہ اس سرٹیفکیٹ کی تصدیق نہیں کرتا۔',
  'Signed by {name}, and the message has not changed, but the certificate is out of date.': '{name} کے دستخط، اور پیغام نہیں بدلا، لیکن سرٹیفکیٹ کی مدت ختم ہو چکی ہے۔',
  'Signed by {name}, but the message has changed since it was signed. Do not rely on what it says.': '{name} کا دستخط شدہ، مگر دستخط کے بعد پیغام بدل دیا گیا ہے۔ اس کی باتوں پر بھروسا نہ کریں۔',
  'Signed by {name}, but the message names no sender to compare the certificate with.': '{name} کے دستخط، لیکن پیغام میں کوئی بھیجنے والا درج نہیں جس سے سرٹیفکیٹ کا موازنہ کیا جائے۔',
  'Signed by {name}, who is not the sender: the certificate is for {email}, and the message says it is from {from}.': '{name} کے دستخط، جو بھیجنے والے نہیں ہیں: سرٹیفکیٹ {email} کا ہے، اور پیغام کہتا ہے کہ یہ {from} کی طرف سے ہے۔',
  'Signed by {name}. The signature is valid and the message has not changed since it was signed.': '{name} کا دستخط شدہ۔ دستخط درست ہے اور دستخط کے بعد سے پیغام میں کوئی تبدیلی نہیں ہوئی۔',
  'Signed on': 'دستخط کی تاریخ',
  'Signing in to {provider}\'s servers…': '{provider} کے سرورز میں سائن ان ہو رہا ہے…',
