  'Signs in with the account\'s password.': 'اکاؤنٹ کے پاس ورڈ سے سائن ان ہوتا ہے۔',
  'Signs in with the account\'s password. The server also offers OAuth 2.0, which works once the provider has registered this application.': 'اکاؤنٹ کے پاس ورڈ سے سائن ان ہوتا ہے۔ سرور OAuth 2.0 بھی پیش کرتا ہے، جو فراہم کنندہ کے اس ایپلیکیشن کو رجسٹر کرنے پر کام کرتا ہے۔',
