  'Every page chosen already has text, so there was nothing to recognise.': 'منتخب کیے گئے ہر صفحے پر پہلے سے متن موجود ہے، اس لیے پہچاننے کو کچھ نہیں تھا۔',
  'Finding the scanned pages…': 'اسکین شدہ صفحات تلاش کیے جا رہے ہیں…',
