  'Page {page}': 'صفحہ {page}',
  'Page {page} cannot be redefined.': 'صفحہ {page} کو دوبارہ متعین نہیں کیا جا سکتا۔',
  'Pages that already have text are left as they are. The words are added as an invisible layer, so the pages look exactly as they did, and can then be searched, selected and copied. Nothing leaves this computer.': 'جن صفحات پر پہلے سے متن ہے وہ جیسے ہیں ویسے ہی رہتے ہیں۔ الفاظ ایک نظر نہ آنے والی تہہ کے طور پر شامل کیے جاتے ہیں، اس لیے صفحات بالکل ویسے ہی دکھتے ہیں جیسے تھے، اور پھر ان میں تلاش، انتخاب اور کاپی کی جا سکتی ہے۔ کچھ بھی اس کمپیوٹر سے باہر نہیں جاتا۔',
  'Reading page {page} of {count}…': 'صفحہ {page} از {count} پڑھا جا رہا ہے…',
  'Recognise': 'پہچانیں',
  'Recognise Text': 'متن پہچانیں',
  'Recognise Text was cancelled. Nothing was changed.': 'متن پہچاننا منسوخ کر دیا گیا۔ کچھ تبدیل نہیں ہوا۔',
  'Recognise Text: the words in scanned pages found, so they can be searched, selected and copied; the pages look as they did': 'متن پہچانیں: اسکین شدہ صفحات کے الفاظ ڈھونڈے جاتے ہیں تاکہ ان میں تلاش، انتخاب اور کاپی ہو سکے؛ صفحات ویسے ہی دکھتے ہیں جیسے تھے',
  'Recognise Text…': 'متن پہچانیں…',
  'Scans': 'اسکین',
  'Text could not be recognised: {reason}': 'متن پہچانا نہیں جا سکا: {reason}',
  'Text recognised on {count} page. Find, select and copy now work on it.': { one: '{count} صفحے پر متن پہچان لیا گیا۔ اب اس میں تلاش، انتخاب اور کاپی ہو سکتی ہے۔', other: '{count} صفحات پر متن پہچان لیا گیا۔ اب ان میں تلاش، انتخاب اور کاپی ہو سکتی ہے۔' },
  'The picture could not be read.': 'تصویر پڑھی نہیں جا سکی۔',
