  'The {count} selected page': { one: 'منتخب کیا گیا {count} صفحہ', other: 'منتخب کیے گئے {count} صفحات' },
  'There is no page {page} in this PDF.': 'اس پی ڈی ایف میں صفحہ {page} نہیں ہے۔',
