  'Text Direction: across, or turned to read down or up': 'متن کی سمت: افقی، یا اس طرح گھمایا ہوا کہ اوپر سے نیچے یا نیچے سے اوپر پڑھا جائے',
  'Align Text: the words at the top, middle or bottom of the box': 'متن کی سیدھ: الفاظ باکس کے اوپر، وسط میں یا نیچے',
  "Margins: the room between the box's edge and its words": 'حاشیے: باکس کے کنارے اور اس کے الفاظ کے درمیان جگہ',
  "Table Styles: Word's own, in this document's theme colours; now {style}": 'ٹیبل اسٹائلز: Word کے اپنے، اس دستاویز کے تھیم رنگوں میں؛ اب {style}',
  "Table Styles: Word's own, in this document's theme colours; now none": 'ٹیبل اسٹائلز: Word کے اپنے، اس دستاویز کے تھیم رنگوں میں؛ اب کوئی نہیں',
  "Line Style: the pen's line for the borders it draws": 'لائن اسٹائل: قلم سے بنائے جانے والے بارڈرز کی لائن',
