  'Pen Colour: now {colour}': 'قلم کا رنگ: اب {colour}',
  "Borders: lines round, between or through the selected cells, in the pen's line": 'بارڈرز: منتخب سیلز کے گرد، درمیان یا آر پار لکیریں، قلم کی لکیر میں',
  "Shading: the selected cells' background": 'شیڈنگ: منتخب سیلز کا پس منظر',
  'Align Table: the table at the left margin, centred or at the right': 'ٹیبل کی سیدھ: ٹیبل بائیں حاشیے پر، درمیان میں یا دائیں جانب',
