  'AutoFit: the table to the window, to fixed column widths, or to its contents': 'خودکار فٹ: ٹیبل کو ونڈو، مقررہ کالم چوڑائیوں یا اس کے مواد کے مطابق کریں',
  "Text Direction: the selected cells' words across, or turned to read down or up": 'متن کی سمت: منتخب سیلز کے الفاظ افقی، یا اس طرح گھمائے ہوئے کہ اوپر سے نیچے یا نیچے سے اوپر پڑھے جائیں',
  'Cell Margins: the room inside every cell of the table': 'سیل کے حاشیے: ٹیبل کے ہر سیل کے اندر کی جگہ',
  'Cell Alignment: the words at the top, centre or bottom of the selected cells; now {align}': 'سیل کی سیدھ: منتخب سیلز میں الفاظ اوپر، درمیان یا نیچے؛ ابھی {align}',
  "Sort: the table's rows by the caret's column, its header row kept at the top": 'ترتیب دیں: ٹیبل کی قطاریں کرسر والے کالم کے مطابق، ہیڈر قطار سب سے اوپر ہی رہتی ہے',
  'Convert to Text: each row a paragraph, its cells between tabs or commas': 'متن میں تبدیل کریں: ہر قطار ایک پیراگراف، اس کے سیلز کے درمیان ٹیبز یا کوما',
  "Formula: a field in the caret's cell worked out from the numbers above or to the left of it, or from cells like B2 and B2:B4, as Word's =SUM(ABOVE)": 'فارمولا: کرسر والے سیل میں ایک فیلڈ، جس کا حساب اس کے اوپر یا بائیں جانب کے نمبروں سے، یا B2 اور B2:B4 جیسے سیلز سے لگایا جاتا ہے، جیسے Word کا =SUM(ABOVE)',
  'Display for Review: how tracked changes are shown': 'جائزے کے لیے ڈسپلے: ٹریک شدہ تبدیلیاں کیسے دکھائی جائیں',
