  'Close Master View first: Slide Size changes the slides and their masters together.': 'پہلے ماسٹر ویو بند کریں: سلائیڈ کا سائز سلائیڈز اور ان کے ماسٹرز کو ایک ساتھ بدلتا ہے۔',
