  'Mark All as Read: {count} comment thread has words you have not read; mark every comment in the presentation read': { one: 'سب کو پڑھا ہوا نشان زد کریں: {count} تبصرہ دھاگے میں ایسے الفاظ ہیں جو آپ نے نہیں پڑھے؛ پریزنٹیشن کا ہر تبصرہ پڑھا ہوا نشان زد کریں', other: 'سب کو پڑھا ہوا نشان زد کریں: {count} تبصرہ دھاگوں میں ایسے الفاظ ہیں جو آپ نے نہیں پڑھے؛ پریزنٹیشن کا ہر تبصرہ پڑھا ہوا نشان زد کریں' },
  'Maximize': 'زیادہ سے زیادہ کریں',
  'Maximize: the content keeps its size and may run off the edges of the new slide': 'زیادہ سے زیادہ کریں: مواد اپنا سائز رکھتا ہے اور نئی سلائیڈ کے کناروں سے باہر جا سکتا ہے',
  'Now {width} by {height} cm. Everything on the slides is scaled and centred to suit the new size.': 'ابھی {width} x {height} cm۔ سلائیڈز پر سب کچھ نئے سائز کے مطابق چھوٹا بڑا اور درمیان میں کیا جاتا ہے۔',
  'On-screen Show (16:10)': 'اسکرین شو (16:10)',
  'Slide Size: Standard, Widescreen or a size of your own': 'سلائیڈ کا سائز: معیاری، وائڈ اسکرین یا آپ کا اپنا سائز',
  'Slide Size: the slides are {width} by {height} cm, {ratio}; Standard, Widescreen or a size of your own, with what is on them scaled to fit': 'سلائیڈ کا سائز: سلائیڈز {width} x {height} cm ہیں، {ratio}؛ معیاری، وائڈ اسکرین یا آپ کا اپنا سائز، ان پر موجود سب کچھ مطابق چھوٹا بڑا کر کے',
  'Slides sized for': 'سلائیڈز کا سائز اس کے لیے',
  'Standard (4:3)': 'معیاری (4:3)',
